-- Лекция III: Дроби
DELETE FROM lectures WHERE level = 3;

INSERT INTO lectures (level, title, sections) VALUES (
  3,
  'Дроби',
  '[
    {"type": "professor", "text": "Сегодня вы узнаете, что число не обязано быть целым. Некоторых это пугает. Хорошо. Страх — признак того, что мозг наконец проснулся."},
    {"type": "heading", "text": "Целое не всегда целое"},
    {"type": "text", "text": "До сих пор вы работали с числами как с кирпичами — твёрдыми, неделимыми, удобными. Но реальность не состоит из кирпичей. Реальность состоит из половин, третей, кусков пирога, которые делят на пятерых, и остатка хлеба, который никогда не делится поровну. Дробь — это число, которое говорит правду: не всё в этом мире целое."},
    {"type": "text", "text": "Египтяне знали это лучше всех. Их система дробей была устроена странно — почти всё представлялось как сумма дробей вида 1/n: 1/2, 1/3, 1/7. Никаких 2/3 — только 1/2 + 1/6. Звучит как пытка. Но именно этой пыткой строили пирамиды, делили землю после разлива Нила и платили рабочим хлебом, который делился на доли."},
    {"type": "heading", "text": "Анатомия дроби"},
    {"type": "text", "text": "У дроби два лица. Числитель — сверху — говорит сколько частей у вас есть. Знаменатель — снизу — говорит на сколько частей разделено целое. 3/4 — это не загадочный символ. Это три кусочка из четырёх. Простое яблоко, разрезанное на четыре части, три из которых лежат перед вами, а одну кто-то уже съел."},
    {"type": "formula", "text": "a/b: a — числитель, b — знаменатель", "hint": "Знаменатель внизу — он стоит на земле, держит дробь. Числитель сверху — он считает."},
    {"type": "heading", "text": "Общий знаменатель — язык, на котором дроби разговаривают"},
    {"type": "text", "text": "Сложить 1/2 и 1/3 напрямую невозможно — это как складывать яблоки с километрами. Половины и трети — разные языки. Чтобы дроби могли говорить друг с другом, их нужно перевести на общий язык — общий знаменатель. Для 1/2 и 1/3 это 6: половина становится 3/6, треть становится 2/6. Теперь они говорят на одном языке, и 3/6 + 2/6 = 5/6 — фраза, которую обе понимают."},
    {"type": "formula", "text": "1/2 + 1/3 = 3/6 + 2/6 = 5/6", "hint": "Общий знаменатель — наименьшее общее кратное знаменателей. Для 2 и 3 это 6."},
    {"type": "quote", "text": "\"Бог создал целые числа, всё остальное — дело рук человека.\" — Леопольд Кронекер, математик XIX века, который не доверял даже дробям. Не будьте как Кронекер. Дроби — ваши друзья."},
    {"type": "heading", "text": "Умножение дробей — единственная честная операция"},
    {"type": "text", "text": "Здесь начинается приятный сюрприз. Умножение дробей — единственная операция, которая делается без всяких общих знаменателей. Числитель на числитель, знаменатель на знаменатель. Никаких приведений, никаких хитростей. 1/2 умножить на 2/3 — это просто 1×2 на 2×3, то есть 2/6, что сокращается до 1/3. Иногда математика добра к вам без всяких условий."},
    {"type": "formula", "text": "(a/b) × (c/d) = (a×c)/(b×d)", "hint": "Прямо, без затей. Сократить результат — отдельный шаг, но не обязательный."},
    {"type": "heading", "text": "Деление дробей — перевёрнутое умножение"},
    {"type": "text", "text": "Разделить на дробь — значит умножить на её перевёрнутую версию. 1/2 разделить на 1/3 равно 1/2 умножить на 3/1, то есть на 3. Звучит как магия, но это просто следствие того, что деление и умножение — зеркала друг друга, о чём вы узнали на прошлой лекции. Индийские математики формализовали это правило тысячу лет назад, и с тех пор оно не подводило никого, кто его правильно запомнил."},
    {"type": "formula", "text": "(a/b) ÷ (c/d) = (a/b) × (d/c)", "hint": "Перевернуть вторую дробь и умножить. \"Деление — это умножение на перевёртыш\"."},
    {"type": "heading", "text": "Смешанные числа — дроби в маскировке"},
    {"type": "text", "text": "1 целая и 3/4 — это смешанное число, и оно ничем не отличается от 7/4. Это одно и то же число, надевшее два разных костюма. Чтобы перейти от смешанного числа к дроби: умножьте целую часть на знаменатель, добавьте числитель, оставьте тот же знаменатель. 1 и 3/4 → (1×4 + 3)/4 = 7/4. Маги, которые путают эти два костюма, проигрывают бои из-за того что не узнали собственное заклинание."},
    {"type": "heading", "text": "Зачем вам это в бою"},
    {"type": "text", "text": "Заклинания дробей требуют записи — таймер на них длиннее, но цена ошибки выше. Многие из вас впервые откроют Гримуар не для красоты, а чтобы записать промежуточный шаг. Это нормально. Записывать — не слабость. Записывать — то, что отличает мага от фокусника."},
    {"type": "outro", "text": "На сегодня хватит. Дроби пугают только тех, кто не видел в них кусков яблока, хлеба и времени. Возьмите Гримуар. Запишите первый пример. И помните: Кронекер был неправ."}
  ]'::jsonb
);
